 *                                _
 *              ___ ___ ___ _____|_|_ _ _____
 *             | . |  _| -_|     | | | |     |  LICENCE
 *             |  _|_| |___|_|_|_|_|___|_|_|_|
 *             |_|
 *
 *   PROGRAMOVÁNÍ  <>  DESIGN  <>  PRÁCE/PODNIKÁNÍ  <>  HW A SW
 *
 * Tento zdrojový kód je součástí výukových seriálů na
 * IT sociální síti WWW.ITNETWORK.CZ
 *
 * Kód spadá pod licenci prémiového obsahu a vznikl díky podpoře
 * našich členů. Je určen pouze pro osobní užití a nesmí být šířen.
 * Více informací na http://www.itnetwork.cz/licence
 */


const API_URL = "http://localhost:8080";

export class HttpRequestError extends Error {
    constructor(response) {
        super(`Network response was not ok: ${response.status} ${response.statusText}`);
        this.response = response;
    }
}

fetch(apiUrl, allRequestOptions)
    .then((response) => {
        return response.text(); // Získejte textovou odpověď
    })
    .then((text) => {
        console.log(text); // Zkontrolujte obsah odpovědi
        try {
            const json = JSON.parse(text); // Pokuste se to analyzovat
            return json;
        } catch (error) {
            console.error("Chyba při analýze JSON:", error);
        }
    })
    .catch((error) => {
        throw error;
    });


export const apiGet = (url, params) => {
    const filteredParams = Object.fromEntries(
        Object.entries(params || {}).filter(([_, value]) => value != null)
    );

    const queryString = new URLSearchParams(filteredParams).toString();
    const apiUrl = queryString ? `${url}?${queryString}` : url;  // Pokud jsou parametry, přidá se "?", jinak ne

    const requestOptions = {
        method: "GET",
    };

    return fetchData(apiUrl, requestOptions);
};


export const apiPost = (url, data) => {
    const requestOptions = {
        method: "POST",
        headers: {"Content-Type": "application/json"},
        body: JSON.stringify(data),
    };

    return fetchData(url, requestOptions);
};

export const apiPut = (url, data) => {
    const requestOptions = {
        method: "PUT",
        headers: {"Content-Type": "application/json"},
        body: JSON.stringify(data),
    };

    return fetchData(url, requestOptions);
};

export const apiDelete = (url) => {
    const requestOptions = {
        method: "DELETE",
    };

    return fetchData(url, requestOptions).then((response) => {
        // If the response is empty (status 204), return null
        return response.status === 204 ? null : response.json();
    });
};
